const BEATS={"a1s1":[[2,"Rumour spreads the false story that Hotspur won at Shrewsbury"],[17,"Lord Bardolph brings Northumberland the false news of victory"],[24,"Travers heard that the rebels lost"],[38,"Morton reports Hotspur's death and the rebels' defeat"],[39,"Northumberland throws off his crutch and calls for chaos"],[44,"The Archbishop of York has risen in a holy cause"]],"a1s2":[[49,"Falstaff asks about his urine and mocks his tiny page"],[59,"The Lord Chief Justice calls Falstaff over"],[65,"Falstaff pretends to be deaf"],[97,"His Shrewsbury service has gilded over Gad's Hill"],[111,"The King has separated Falstaff from Hal"],[123,"Falstaff will turn his diseases to profit"]],"a1s3":[[127,"The Archbishop asks the rebels for their views"],[136,"Lord Bardolph's warning: plan before you build"],[139,"Hastings: the King's forces are split three ways"],[144,"The Archbishop scorns the fickle crowd"]],"a2s1":[[150,"The Hostess has Fang and Snare arrest Falstaff"],[174,"The Lord Chief Justice stops the brawl"],[183,"The Hostess: he swore to marry me"],[187,"The Justice orders Falstaff to pay"],[201,"The Hostess agrees to pawn her plate for him"],[212,"News that troops have gone north"]],"a2s2":[[227,"Hal is weary and ashamed of his low tastes"],[239,"His heart bleeds for his father, but he cannot show it"],[262,"Bardolph brings Falstaff's letter"],[271,"The letter warns Hal against Poins"],[294,"Hal and Poins plan to spy on Falstaff as waiters"]],"a2s3":[[301,"Northumberland says his honour is pledged"],[302,"Lady Percy's lament for Hotspur"],[304,"Lady Northumberland urges Scotland"],[306,"Northumberland decides to flee to Scotland"]],"a2s4":[[318,"The Hostess fusses over a tipsy Doll"],[348,"Pistol arrives and quarrels with Doll"],[387,"Falstaff drives Pistol out"],[403,"Doll tells Falstaff to think of heaven"],[407,"Falstaff mocks Hal and Poins, who overhear"],[428,"Hal and Poins reveal themselves"],[463,"News of war: Hal leaves at once"],[469,"Falstaff is called to the wars; Doll weeps"]],"a3s1":[[483,"The sleepless King: 'Uneasy lies the head that wears a crown'"],[492,"He recalls Richard's prophecy"],[495,"Warwick: there is a history in all men's lives"],[497,"Glendower is dead; the King agrees to rest"]],"a3s2":[[502,"Shallow and Silence talk of youth and death"],[532,"Falstaff arrives to collect recruits"],[540,"The recruits are called: Mouldy, Shadow, Wart, Feeble, Bullcalf"],[603,"'We have heard the chimes at midnight'"],[606,"Bullcalf and Mouldy bribe Bardolph"],[610,"Feeble: 'we owe God a death'"],[621,"Falstaff frees Mouldy and Bullcalf"],[635,"Falstaff plans to fleece Shallow"]],"a4s1":[[643,"Northumberland has gone to Scotland"],[654,"Westmoreland rebukes the Archbishop"],[655,"The Archbishop: the realm is diseased"],[669,"The rebels hand over their articles"],[675,"Mowbray fears no peace can last"]],"a4s2":[[687,"Prince John rebukes the Archbishop"],[693,"He swears to redress the grievances"],[696,"The rebels send their army home"],[723,"Westmoreland arrests the rebel leaders"],[727,"Prince John: 'I pawn'd thee none'"]],"a4s3":[[736,"Colevile surrenders to Falstaff's reputation"],[741,"Prince John rebukes Falstaff's lateness"],[758,"Colevile is sent to execution"],[764,"Falstaff's praise of sherris-sack"],[768,"Falstaff heads for Gloucestershire"]],"a4s4":[[772,"The King plans a crusade once the rebels are crushed"],[781,"He urges Clarence to keep Hal's love"],[788,"Warwick: Hal studies his companions like a strange tongue"],[792,"The Gaultree rebels are taken"],[796,"Northumberland is defeated"],[797,"Good news makes the King sick; he collapses"]],"a4s5":[[813,"The crown is set on the King's pillow"],[829,"Hal, thinking him dead, takes the crown"],[844,"The King wakes and accuses Hal"],[853,"'Thy wish was father, Harry, to that thought'"],[854,"Hal's defence"],[855,"The King's confession and last advice"],[865,"He will die in the Jerusalem chamber"]],"a5s1":[[869,"Shallow insists Falstaff stay"],[875,"Davy's farm business"],[887,"Davy asks favour for the knave Visor"],[897,"Falstaff plans to amuse Hal with Shallow"]],"a5s2":[[905,"The King is dead"],[910,"The Lord Chief Justice expects the worst"],[927,"Henry V reassures his brothers"],[932,"The Justice defends himself"],[933,"Henry makes him 'a father to my youth'"]],"a5s3":[[937,"Supper in Shallow's orchard"],[942,"Silence sings"],[1008,"Pistol: Hal is king"],[1016,"Falstaff: 'the laws of England are at my commandment'"]],"a5s4":[[1021,"The beadles drag off the Hostess and Doll"],[1022,"A man they beat has died"],[1024,"The women wish for Falstaff"]],"a5s5":[[1043,"Falstaff waits for the procession"],[1056,"Pistol: Doll is in prison"],[1063,"'God save thee, my sweet boy!'"],[1067,"'I know thee not, old man'"],[1071,"Falstaff hopes to be sent for in private"],[1077,"Falstaff is taken to the Fleet"],[1086,"Prince John foresees war in France"],[1089,"The Epilogue promises more of Sir John"]]};
